// Fallback response for non-text messages (voice notes, photos, documents)
const sender = $json.from || ($json.contacts && $json.contacts[0] && $json.contacts[0].wa_id);
return [{
  json: {
    to: sender,
    fallback_message: "Hello, thank you for reaching out to Green Heights. I can process text messages on this chat; our sales executive has been notified and will call you directly.",
    handover_required: true,
    handover_reason: "Received non-text message (voice note or media)"
  }
}];

// Section 17A: Build Context & Verify Price List Freshness (<24h)
// In production, this reads from Facts and Availability tables.
const reraNumber = 'P02400008899';
const allowedPrices = [9817500, 12757500, 13177500];
const priceUpdatedTimestamp = new Date().getTime(); // Fresh
const ageHours = (Date.now() - priceUpdatedTimestamp) / 36e5;
const priceOk = ageHours < 24;

return [{
  json: {
    ...$json,
    rera_number: reraNumber,
    allowed_amounts: allowedPrices,
    price_age_hours: Math.round(ageHours),
    price_ok: priceOk,
    kill_switch: false
  }
}];

// Section 17B: Strict Reply Validator Code Node (SC-I1)
const out = $json.output || $json;
const ctx = $('Build Context & Check Price Freshness (SC-I4)').first().json;
const reply = out.reply || out.text || '';
const reasons = [];

// 1. RERA Check
if (/₹/.test(reply) && !reply.includes(ctx.rera_number)) {
  reasons.push('RERA registration number missing from message with price.');
}

// 2. Amount verification
const amounts = [...reply.matchAll(/₹\s?([\d,.]+)\s?(crore|cr|lakh|L)?/gi)].map(m => {
  let n = parseFloat(m[1].replace(/,/g, ''));
  const u = (m[2] || '').toLowerCase();
  if (u === 'crore' || u === 'cr') n *= 1e7;
  else if (u === 'lakh' || u === 'l') n *= 1e5;
  return Math.round(n);
});

if (amounts.length && !ctx.price_ok) {
  reasons.push('Price was quoted but price list is older than 24 hours.');
}

amounts.forEach(a => {
  if (!ctx.allowed_amounts.some(x => Math.abs(x - a) <= 1000)) {
    reasons.push('Amount ₹' + a + ' is not on the approved live price list.');
  }
});

// 3. Prohibited phrases check
if (/(guarantee|assured|100%|offer ends|possession by)/i.test(reply)) {
  reasons.push('Prohibited marketing commitment or unapproved possession phrase detected.');
}

// 4. Word length check
if (reply.split(/\s+/).length > 120) {
  reasons.push('Message exceeds 120 words maximum.');
}

return [{
  json: {
    ...out,
    phone: ctx.phone,
    reply: reply,
    pass: reasons.length === 0,
    reasons: reasons,
    handover_required: out.handover_required || (reasons.length > 0)
  }
}];

