// Section 17C: Filter leads due for follow-up (SC-I7)
// Uses date <= today, nudge_count < 3, opted_out != yes
const today = new Date().toISOString().slice(0, 10);
const sampleLeads = [
  { phone: '+919876543210', name: 'Ravi Kumar', next_followup_date: today, nudge_count: 1, opted_out: 'no', stage: 'visit_scheduled' }
];

return sampleLeads.filter(j => {
  return j.next_followup_date &&
    j.next_followup_date <= today &&
    !['booked', 'lost'].includes(j.stage) &&
    String(j.opted_out).toLowerCase() !== 'yes' &&
    Number(j.nudge_count || 0) < 3;
}).map(l => ({ json: l }));
